INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(13801, 'Psalms 58:10', 'Psalms', 58, 10, '&nbsp;صادقان به خوشحاله شى کله چې دوئ انتقام وګورى، نو خپلې پښې به د شريرانو په وينو کښې ووينځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13802, 'Psalms 58:11', 'Psalms', 58, 11, '&nbsp;او خلق به دا ووائى، ”بې‌شکه چې صادقان به خپل اجر ومومى، بې‌شکه چې يو داسې خُدائ شته چې د دُنيا اِنصاف کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13803, 'Psalms 59:1', 'Psalms', 59, 1, '&nbsp;ما د خپلو دشمنانو نه خلاص کړه، پاکه خُدايه، څوک چې زما خلاف حملې کوى ما د هغوئ نه بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13804, 'Psalms 59:2', 'Psalms', 59, 2, '&nbsp;ما د بدکارانو نه بچ کړه، ما د قاتلانو نه آزاد کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13805, 'Psalms 59:3', 'Psalms', 59, 3, '&nbsp;زما د وژلو دپاره پټ ناست دى، او خطرناک دشمنان زما خلاف رايوځائ شوى دى، کۀ څۀ هم ما د دوئ خلاف هيڅ ګناه نۀ ده کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13806, 'Psalms 59:4', 'Psalms', 59, 4, '&nbsp;چا سره مې هم بد نۀ دى کړى خو بيا هم ځان د حملې دپاره تياروى. راپاڅه او حال مې ګوره چې څۀ وشول او مدد دپاره راشه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13807, 'Psalms 59:5', 'Psalms', 59, 5, '&nbsp;اے مالِکه قادر مطلق خُدايه، د بنى اِسرائيلو خُدايه، راپاڅه او ټولو قومونو له سزا ورکړه، دې بدکارو غدارانو باندې هيڅ رحم مۀ کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13808, 'Psalms 59:6', 'Psalms', 59, 6, '&nbsp;هغوئ هر ماښام لکه د کوڅه ډب سپو په شان راوځى، کله چې د ښار په لارو کوڅو کښې ګشت کوى نو غپيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13809, 'Psalms 59:7', 'Psalms', 59, 7, '&nbsp;وګورئ چې د خپلو خُلو نه څنګه ګډې وډې نوستل کوى، د دوئ ‎ژبې لکه د تېرو تُورو په شان غوڅول کوى، دوئ په زړۀ کښې وائى چې، ”څوک هم مونږ نه خبر نۀ دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13810, 'Psalms 59:8', 'Psalms', 59, 8, '&nbsp;خو تۀ، اے مالِکه خُدايه، هغوئ پورې خندا کوې، تۀ په دوئ ټولو غېر قومونو پورې مسخرې کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13811, 'Psalms 59:9', 'Psalms', 59, 9, '&nbsp;پاکه خُدايه تۀ زما زور يې، زما سترګې تا ته دى، خو هم دا تۀ زما پناه ګاه يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13812, 'Psalms 59:10', 'Psalms', 59, 10, '&nbsp;زما مينه ناک خُدائ به د مدد دپاره ما سره جوړه شى، او ما ته به د خپلو دشمنانو شکست راپه ګوته کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13813, 'Psalms 59:11', 'Psalms', 59, 11, '&nbsp;خو تۀ دوئ مۀ وژنه، اے مالِکه زمونږ ډاله، ځکه چې زما قوم به دا سبق هېر کړى. په خپل طاقت دې دوئ تس نس کړه او تۀ دوئ ښکته راګزار کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13814, 'Psalms 59:12', 'Psalms', 59, 12, '&nbsp;د خپلې خولې او د شونډو د ګناه په وجه چې کومه کوى، په هم هغه ښيرو او دروغو او کبر کښې دې په خپله راګېر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13815, 'Psalms 59:13', 'Psalms', 59, 13, '&nbsp;په خپل قهر سره دې دوئ تباه کړه، چې يو هم پاتې نۀ شى بلکل يې جارُو کړه. نو ټوله دُنيا په دې خبر کړه، چې خُدائ په بنى اِسرائيلو حکومت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13816, 'Psalms 59:14', 'Psalms', 59, 14, '&nbsp;زما دشمنان هر ماښام لکه د کوڅه ډب سپو راواپس کيږى، کله چې د ښار په لارو کوڅو کښې ګشت کوى نو غپيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13817, 'Psalms 59:15', 'Psalms', 59, 15, '&nbsp;ګرځى لکه سپى هسې خوراک پسې، پاتې چې شى اوږى، کوى سپى هسې غرار.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13818, 'Psalms 59:16', 'Psalms', 59, 16, '&nbsp;خو زۀ به ستا طاقت بيانوم، زۀ به ستا مينه هر سحر په خوشحالۍ سره ستايم. هم دا تۀ زما اوچته قلعه او پناه ګاه يې او په تکليفونو کښې زما خلاصون يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13819, 'Psalms 59:17', 'Psalms', 59, 17, '&nbsp;تۀ زما زور او طاقت يې زۀ به ستا ثناء صِفت کوم، تۀ په خپله زما پناه ګاه يې، پاکه خُدايه او کوې ما سره مينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13820, 'Psalms 60:1', 'Psalms', 60, 1, '&nbsp;تا مونږ رد کړو او زمونږ دېوالونه دې راوغورزول اے خُدايه. مونږ ته په قهر شوے وې خو دوباره خپل مقام واپس راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13821, 'Psalms 60:2', 'Psalms', 60, 2, '&nbsp;تا په زمکه زلزله راوستله او هغه وشلېدله، ځکه چې ټوله خوځيږى چاؤدونه يې بند کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13822, 'Psalms 60:3', 'Psalms', 60, 3, '&nbsp;تا خپلو خلقو ته ډيرې سختې ښودلى دى، مے دې مونږ ته راکړل او ډغرې مو وخوړلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13823, 'Psalms 60:4', 'Psalms', 60, 4, '&nbsp;تا د هغوئ دپاره جنډا اوچته کړه څوک چې تا نه يريږى، چې دا به د حملې خلاف د پناه نښه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13824, 'Psalms 60:5', 'Psalms', 60, 5, '&nbsp;په خپل ښى لاس دې مونږ سره مدد وکړه او مونږ بچ کړه، چې چا سره چې تۀ مينه کوې هغوئ ته خلاصون ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13825, 'Psalms 60:6', 'Psalms', 60, 6, '&nbsp;د خپل مقدس ځائ نه خُدائ داسې وفرمائيل، ”د فتحې په خوشحالۍ کښې به زۀ شِکم تقسيم کړم، او د سُکات د درې ناپ تول به وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13826, 'Psalms 60:7', 'Psalms', 60, 7, '&nbsp;جِلعاد او منسى دواړه زما دى. اِفرائيم زما ټوپۍ او يهوداه زما د بادشاهۍ کونټۍ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13827, 'Psalms 60:8', 'Psalms', 60, 8, '&nbsp;موآب زما د وينځلو ښانک دے او هغه به زما خِدمتګار وى. او زۀ په ادوم باندې خپلې څپلۍ پاکومه او زۀ به په فلستيه مُلک باندې د کاميابۍ چغه وهم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13828, 'Psalms 60:9', 'Psalms', 60, 9, '&nbsp;خو څوک به ما د قلعې پوخ ښار ته داخل کړى؟ څوک به ما ادوم ته ورسوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13829, 'Psalms 60:10', 'Psalms', 60, 10, '&nbsp;اے خُدايه، تا مونږه رد کړى يُو څۀ؟ تۀ به نور زمونږ لښکرو سره په لار نۀ ځې څۀ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13830, 'Psalms 60:11', 'Psalms', 60, 11, '&nbsp;د دشمن خلاف زمونږ مدد وکړه، ځکه چې د انسانانو مدد بې‌فائدې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13831, 'Psalms 60:12', 'Psalms', 60, 12, '&nbsp;د خُدائ مدد به مونږ له کاميابى راکړى، هغه به زمونږ دشمنان د پښو لاندې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13832, 'Psalms 61:1', 'Psalms', 61, 1, '&nbsp;اے پاکه خُدايه، زما سوال زارى واوره، او زما دُعا ته غوږ ونيسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13833, 'Psalms 61:2', 'Psalms', 61, 2, '&nbsp;د دُنيا د آخر نه تا ته نعرې وهم، کله چې زړۀ زما بې‌حاله شى. اوچت ګټ ته مې بوځه او ما ته هلته پناه راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13834, 'Psalms 61:3', 'Psalms', 61, 3, '&nbsp;ځکه چې تۀ زما مضبوط برج او پناه ګاه يې، چرته چې د دشمن نه په امان کښې يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13835, 'Psalms 61:4', 'Psalms', 61, 4, '&nbsp;زۀ غواړم چې تر ابده ستا مقدس ځائ کښې اوسېږم، او ستا د وزرو لاندې پناه واخلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13836, 'Psalms 61:5', 'Psalms', 61, 5, '&nbsp;تا، زما منښتې پاکه خُدايه، اورېدلې دى، او هم هغه ميراث دې ما ته راکړے دے کوم چې هغوئ ته ورکوې څوک چې ستا نه يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13837, 'Psalms 61:6', 'Psalms', 61, 6, '&nbsp;بادشاه له د عمر ورځې ډيرې کړه، د هغۀ عمر تر ډېرو نسلونو پورې زيات کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13838, 'Psalms 61:7', 'Psalms', 61, 7, '&nbsp;هغه دې د خُدائ پاک په حضور کښې د تل دپاره بادشاهى وکړى، هغۀ ته خپله مينه او وفا وروښايه چې دے حفاظت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13839, 'Psalms 61:8', 'Psalms', 61, 8, '&nbsp;نو دغه شان به ټول عمر ستا د نوم ثناء صِفت کوم، چې ما څنګه وعدې درسره کړى دى هغه روزانه پوره کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13840, 'Psalms 62:1', 'Psalms', 62, 1, '&nbsp;زما ځان صرف په خُدائ پاک کښې آرام مومى، ځکه چې زما د خلاصون مالِک هغه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13841, 'Psalms 62:2', 'Psalms', 62, 2, '&nbsp;هغه په خپله زما ګټ او خلاصونکے دے، او زۀ به هيڅکله په لړزان نۀ شم هغه زما د امان ځائ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13842, 'Psalms 62:3', 'Psalms', 62, 3, '&nbsp;تاسو ټول به ترڅو په سړى باندې حملې کوئ؟ کوم کس چې د کچه دېوال او کمزورى باړ په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13843, 'Psalms 62:4', 'Psalms', 62, 4, '&nbsp;دوئ صرف په دې سوچ کښې دى چې هغه د خپل عزت مقام نه راوغورزوى. دوئ له دروغ وئيل خوند ورکوى، په خولۀ خو دوئ برکت ورکوى، خو په زړۀ کښې دوئ لعنت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13844, 'Psalms 62:5', 'Psalms', 62, 5, '&nbsp;اے زما روحه صرف په خُدائ پاک کښې په آرام سره صبر وکړه. ځکه چې زما ټول اُميدونه هغۀ پورې تړلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13845, 'Psalms 62:6', 'Psalms', 62, 6, '&nbsp;هغه په خپله زما ګټ او خلاصونکے دے. او زۀ به هيڅکله په لړزان نۀ شم هغه زما د امان ځائ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13846, 'Psalms 62:7', 'Psalms', 62, 7, '&nbsp;زما عزت او خلاصون د خُدائ له طرفه دے، هغه زما غټ ګټ او پناه ګاه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13847, 'Psalms 62:8', 'Psalms', 62, 8, '&nbsp;اے خلقو هر وخت هغۀ باندې يقين ساتئ. تاسو هغۀ ته د خپل زړۀ مشکل بيانوئ، ځکه چې خُدائ پاک زمونږ پناه ګاه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13848, 'Psalms 62:9', 'Psalms', 62, 9, '&nbsp;عام خلق څۀ حيثيت نۀ لرى د هغۀ په وړاندې، زورَور خلق هم هغه نۀ دى کوم چې دوئ ښکارى، کۀ هغوئ ټول په تله وتلى دا به د هوا نه هم سپک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13849, 'Psalms 62:10', 'Psalms', 62, 10, '&nbsp;چې په ظلم زياتى يقين ونۀ کړئ، او نۀ د غلا د مال اسرا وکړئ. ولې چې ځان ورپورې ونۀ تړئ، هر څومره چې دولت ستا زياتيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13850, 'Psalms 62:11', 'Psalms', 62, 11, '&nbsp;خُدائ پاک يو ځل وفرمائيل، نو ما بار بار واورېدل، چې خُدائ پاک زورَور دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13851, 'Psalms 62:12', 'Psalms', 62, 12, '&nbsp;او چې پاکه خُدايه ستا مينه نۀ ختمېدونکې ده. بې‌شکه چې تۀ هر چا ته د هغوئ د کارونو په مطابق اجر ورکوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13852, 'Psalms 63:1', 'Psalms', 63, 1, '&nbsp;اے خُدايه، تۀ زما خُدائ پاک يې. د زړۀ نه ستا په لټون کښې يم، روح او زما ځان ستا تږے دے، لکه اوبۀ چې نۀ وى په زمکه خشکه او شاړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13853, 'Psalms 63:2', 'Psalms', 63, 2, '&nbsp;تۀ ما په خپل مقدس مقام کښې ليدلے يې، او ستا جلال او زور هم ما ليدلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13854, 'Psalms 63:3', 'Psalms', 63, 3, '&nbsp;ستا نۀ ختمېدونکې مينه د ژوند نه ښۀ ده، نو ځکه به زما شونډې ستا لوئى بيانوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13855, 'Psalms 63:4', 'Psalms', 63, 4, '&nbsp;ترڅو چې زۀ ژوندے يم ستا ثناء صِفت به ادا کوم، او خپل لاسونه به په دُعا کښې ستا په نوم پورته کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13856, 'Psalms 63:5', 'Psalms', 63, 5, '&nbsp;ځان به زما داسې موړ شى لکه په غوره خوراک. زۀ به په خوشحالۍ سره وايم ستا ثناء او صِفت،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13857, 'Psalms 63:6', 'Psalms', 63, 6, '&nbsp;زۀ چې پروت يمه په کټ کښې هم تا يادوم، ستا په حقله شپه کښې ټوله شپه فکر کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13858, 'Psalms 63:7', 'Psalms', 63, 7, '&nbsp;ځکه چې تۀ زما مددګار يې، په سورى د وزرو کښې ستا د خوشحالۍ سندرې وايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13859, 'Psalms 63:8', 'Psalms', 63, 8, '&nbsp;ما خپل ځان تا پورې تړلے دے، ستا زورَور لاس زۀ په امان کښې ساتلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13860, 'Psalms 63:9', 'Psalms', 63, 9, '&nbsp;څوک چې کوشش کوى زما د وژلو، خو دوئ به ټول لاړ شى لاندې د خاورو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13861, 'Psalms 63:10', 'Psalms', 63, 10, '&nbsp;په جنګ کښې به هغوئ لاندې شى د تُورو، او دوئ به شى خوراک د ګيدړانو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13862, 'Psalms 63:11', 'Psalms', 63, 11, '&nbsp;خو بادشاه به خوشحاليږى د خُدائ پاک په نوم، او ټولو چا چې د خُدائ په نوم قسم خوړلے، هغوئ به د هغۀ ثناء صِفت کوى، ځکه چې د دروغژنو خولې به بندې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13863, 'Psalms 64:1', 'Psalms', 64, 1, '&nbsp;اے پاکه خُدايه، زما آواز تۀ واوره، زما ژوند د دشمنانو د يرې نه وساته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13864, 'Psalms 64:2', 'Psalms', 64, 2, '&nbsp;ما د بدعمله د پټو منصوبو نه په امان کړه، ما د بدکردارو د قبيلې نه په امان کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13865, 'Psalms 64:3', 'Psalms', 64, 3, '&nbsp;خپلې ژبې يې لکه د تُورو په شان تېرې کړې دى، او د هغوئ بدې او ترخې خبرې لکه وژونکو غشو په شان دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13866, 'Psalms 64:4', 'Psalms', 64, 4, '&nbsp;هغوئ د پټ ځائ نه په بې‌ګناه کس ګزارونه کوى. دوئ د چا نه نۀ يريږى ناڅاپه پرې ګزارونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13867, 'Psalms 64:5', 'Psalms', 64, 5, '&nbsp;په بدو منصوبو کښې دوئ د يو بل ډاډګيرنه کوى. او په خپلو کښې په مشورې سره پټ دامونه ږدى، په خپلو کښې دا خيال کوى چې څوک به مونږ وګورى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13868, 'Psalms 64:6', 'Psalms', 64, 6, '&nbsp;دوئ په بې‌اِنصافۍ سره منصوبې جوړوى، او دوئ وائى چې، ”مونږ ډېره ښۀ منصوبه جوړه کړُو.“ د انسان عقل او زړۀ دواړه څومره چالاکه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13869, 'Psalms 64:7', 'Psalms', 64, 7, '&nbsp;خو خُدائ پاک به دوئ په غشو باندې ولى، او ناګهانه به دوئ زخمى کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13870, 'Psalms 64:8', 'Psalms', 64, 8, '&nbsp;د دوئ خپلې ژبې به هم دوئ تباه کوى. هر هغه څوک چې دوئ ته ګورى نو په سپکه به خپل سرونه هغوئ پورې خوځوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13871, 'Psalms 64:9', 'Psalms', 64, 9, '&nbsp;او ټول انسانان به وۀ يريږى. دوئ به د خُدائ پاک د شان کارونه بيان کړى، او د هغۀ په کارونو به فکر کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13872, 'Psalms 64:10', 'Psalms', 64, 10, '&nbsp;ټول صادقان دې د مالِک خُدائ خوشحالى وکړى او په هغۀ کښې دې پناه واخلى. او ټول نېکان دې د خُدائ پاک ثناء صِفت ادا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13873, 'Psalms 65:1', 'Psalms', 65, 1, '&nbsp;په صيون کښې، پاکه خُدايه، تۀ د ثناء صِفت لائق يې. منښتې به هم تا ته وړاندې کيږى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13874, 'Psalms 65:2', 'Psalms', 65, 2, '&nbsp;تۀ په خپله د ټولو دُعاګانې اورې، ټول خلق به تا ته راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13875, 'Psalms 65:3', 'Psalms', 65, 3, '&nbsp;کله چې مونږ د خپلو ګناهونو لاندې راګېر شولو، نو زمونږ ټول ګناهونه دې معاف کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13876, 'Psalms 65:4', 'Psalms', 65, 4, '&nbsp;بختور دى هغوئ څوک چې تا په خپله غوره کړى دى، چې ستا په دربار کښې اوسيږى او خپل ځان ته دې نزدې کړى دى. مونږ به ستا د مقدس کور په نعمتونو ماړۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13877, 'Psalms 65:5', 'Psalms', 65, 5, '&nbsp;تا زمونږ دُعا داسې قبوله کړه چې تا زمونږ دپاره د صداقت حېرانونکې کارونه کړى دى، اے زمونږ خلاصونکيه زمونږ پاکه خُدايه. د دُنيا د يو سر نه تر بل سره پورې، او تر لرې سمندرونو پورې تۀ د هر چا اُميد يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13878, 'Psalms 65:6', 'Psalms', 65, 6, '&nbsp;تا چې غرونه په خپل زور ودرولې دى، خپل ځان دې په طاقت سمبال کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13879, 'Psalms 65:7', 'Psalms', 65, 7, '&nbsp;ستا په حُکم د سمندر زورَورى چپې او موجونه قلاريږى، او هم ستا په حُکم د قومونو چغې سورې په قلاريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13880, 'Psalms 65:8', 'Psalms', 65, 8, '&nbsp;ستا د عجيبه کارونو نه دا دُنيا د يو سره تر بله ټوله يريږى، د نمر ختو نه د نمر پرېوتو پورې تۀ د خلقو د خوشحالۍ د آوازونو سبب کېږې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13881, 'Psalms 65:9', 'Psalms', 65, 9, '&nbsp;تۀ د زمکې خيال ساتې اوبۀ ورکوې او ښۀ يې زرخيزه کوې، د خُدائ پاک سيندونه د اوبو نه ډک شُو. نو خلقو ته د غلې دانې بندوبست وشو. نو دغه شان دې په زمکه انتظام وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13882, 'Psalms 65:10', 'Psalms', 65, 10, '&nbsp;قُلبه شوې پټى په باران سيرابه کوې، لوړې ژورې او لوټې يې هواروې. په باران سره يې نرموې، او فصلونو ته يې برکت ورکوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13883, 'Psalms 65:11', 'Psalms', 65, 11, '&nbsp;تا کال ته په آبادۍ سره برکت ورکړو، تر دې چې ګاډۍ او کوڅې دې دانو نه انبار کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13884, 'Psalms 65:12', 'Psalms', 65, 12, '&nbsp;د صحراګانو د څرند ځايونه دې سرسبزه کړل، او د غرونو لمنو ته دې د خوشحالۍ جامې واغوستې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13885, 'Psalms 65:13', 'Psalms', 65, 13, '&nbsp;د څرند ځايونه د رمو نه ډک شو، او ټول پټى د دانو نه ډک شو. هر څيز نعرې وهى او د خوشحالۍ سندرې وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13886, 'Psalms 66:1', 'Psalms', 66, 1, '&nbsp;اے د ټولې دُنيا خلقو خوشحالى وکړئ. خُدائ پاک ته د خوشحالۍ نعرې ووهئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13887, 'Psalms 66:2', 'Psalms', 66, 2, '&nbsp;د هغۀ د نوم د جلال سندرې ووايئ، او د هغۀ جلالى حمد‌و‌ثناء بيان کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13888, 'Psalms 66:3', 'Psalms', 66, 3, '&nbsp;خُدائ پاک ته ووايئ، ”ستا کارونه هيبتناک دى او زور طاقت دې ډېر لوئ دے. نو ځکه ستا ټولو دشمنانو ستا په وړاندې خپل سرونه ټيټ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13889, 'Psalms 66:4', 'Psalms', 66, 4, '&nbsp;په ټوله دُنيا کښې هر يو کس ستا عبادت کوى ستا حمد‌و‌ثناء وائى او ستا د نوم ثناء صِفت کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13890, 'Psalms 66:5', 'Psalms', 66, 5, '&nbsp;خُدائ پاک چې څۀ کړې دى راشئ هغه وګورئ، او هغۀ چې بنيادمو له کوم لوئ کارونه کړى دى هغه وګورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13891, 'Psalms 66:6', 'Psalms', 66, 6, '&nbsp;هغۀ سمندر په وُچه زمکه باندې بدل کړو، نو هغوئ ښۀ خوشحالى وکړه کله چې پېدل په کښې تير شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13892, 'Psalms 66:7', 'Psalms', 66, 7, '&nbsp;هغه د تل دپاره په خپل طاقت بادشاهى کوى، او قومونه د خپل نظر لاندې ساتى چې دوئ خو د دۀ خلاف سرکشى نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13893, 'Psalms 66:8', 'Psalms', 66, 8, '&nbsp;اے ټولو قومونو آواز پورته کړئ، زمونږ د خُدائ پاک ثناء صِفت وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13894, 'Psalms 66:9', 'Psalms', 66, 9, '&nbsp;د هغۀ په لاس کښې زمونږ ژوندون دے زمونږ پښې يې د تيندک خوړلو نه ساتلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13895, 'Psalms 66:10', 'Psalms', 66, 10, '&nbsp;نو پاکه خُدايه تا خو مونږه آزمائيلى يُو، داسې لکه سپين زر دې په اور صفا کړى يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13896, 'Psalms 66:11', 'Psalms', 66, 11, '&nbsp;مونږ دې په جال کښې راګېر کړلو، تا زمونږ په ملا دروند بار کېښودلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13897, 'Psalms 66:12', 'Psalms', 66, 12, '&nbsp;تا زمونږ دشمنان زمونږ په سر باندې تېرېدو ته پرېښودل، او مونږ دې اور او سېلاب نه تير کړُو، خو آخر دې هم مونږ د آرام او برکتونو ځائ ته راوستُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13898, 'Psalms 66:13', 'Psalms', 66, 13, '&nbsp;زۀ به سوزېدونکې قربانۍ ستا کور ته راوړم، خپلې کړې وعدې به تا سره پوره کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13899, 'Psalms 66:14', 'Psalms', 66, 14, '&nbsp;څۀ چې ما منلى وُو هم هغه به وکړم کوم وخت کښې چې زۀ سخته کښې ګېر وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13900, 'Psalms 66:15', 'Psalms', 66, 15, '&nbsp;زۀ به په قربان‌ګاه باندې څربه څاروى پېش کړم، او دې سره به غوَيان او چېلۍ هم قربانى کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');